        static string X(string value){if(value==null)return "";return value.Replace("&","&amp;").Replace("<","&lt;").Replace(">","&gt;").Replace("\"","&quot;").Replace("'","&apos;");}
        static void Entry(ZipArchive zip,string name,string content){var entry=zip.CreateEntry(name,CompressionLevel.Optimal);using(var writer=new StreamWriter(entry.Open(),new UTF8Encoding(false)))writer.Write(content);}
        DateTime? FirstDate(string value){var m=System.Text.RegularExpressions.Regex.Match(value??"",@"(\d{4})[/-](\d{1,2})[/-](\d{1,2})\s+(\d{1,2}):(\d{2})");DateTime d;if(!m.Success||!DateTime.TryParse(m.Groups[1].Value+"-"+m.Groups[2].Value+"-"+m.Groups[3].Value+" "+m.Groups[4].Value+":"+m.Groups[5].Value,out d))return null;return d;}
        DateTime? LastDate(string value){var ms=System.Text.RegularExpressions.Regex.Matches(value??"",@"(\d{4})[/-](\d{1,2})[/-](\d{1,2})\s+(\d{1,2}):(\d{2})");if(ms.Count<2)return null;var m=ms[1];DateTime d;if(!DateTime.TryParse(m.Groups[1].Value+"-"+m.Groups[2].Value+"-"+m.Groups[3].Value+" "+m.Groups[4].Value+":"+m.Groups[5].Value,out d))return null;return d;}
        string ExcelStatus(Dictionary<string,object> row,DateTime now){DateTime? start=FirstDate(Str(row,"registration")),end=LastDate(Str(row,"registration"));if(!start.HasValue||!end.HasValue)return "时间待确认";if(now<start.Value)return "报名未开始";if(now>=end.Value)return "报名已截止";if(Str(row,"remaining")=="0")return "名额已满";return "报名时间内";}
        string Cell(string address,string value,int style){return "<c r=\""+address+"\" s=\""+style+"\" t=\"inlineStr\"><is><t xml:space=\"preserve\">"+X(value)+"</t></is></c>";}
        string NumberCell(string address,double value,int style){return "<c r=\""+address+"\" s=\""+style+"\"><v>"+value.ToString(System.Globalization.CultureInfo.InvariantCulture)+"</v></c>";}
        string DateCell(string address,DateTime? value,int style){return value.HasValue?NumberCell(address,value.Value.ToOADate(),style):Cell(address,"",5);}
        string ValueCell(string address,string value,int style){int n;return int.TryParse(value,out n)?NumberCell(address,n,6):Cell(address,value,style);}
        void ExportExcel(List<Dictionary<string,object>> selected)
        {
            var ordered=selected.Where(r=>!IgnoredActivity(r)).OrderBy(r=>FirstDate(Str(r,"registration"))??DateTime.MaxValue).ThenBy(r=>Str(r,"name"),StringComparer.CurrentCulture).ToList();
            string target;if(testing){target=Path.Combine(dataDir,"未开始活动_测试.xlsx");testXlsx=target;}else{using(var dialog=new SaveFileDialog{FileName="未开始活动_"+DateTime.Now.ToString("yyyy-MM-dd")+".xlsx",Filter="Excel 工作簿 (*.xlsx)|*.xlsx",OverwritePrompt=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;target=dialog.FileName;}}
            string temp=target+".tmp";if(File.Exists(temp))File.Delete(temp);using(var file=File.Create(temp))using(var zip=new ZipArchive(file,ZipArchiveMode.Create,true))WriteExcel(zip,ordered);if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);if(!testing)statusLabel.Text="已导出 Excel："+target;
        }
