            s.Append("<row r=\"1\" ht=\"30\" customHeight=\"1\">").Append(Cell("A1","未开始活动汇总",1)).Append("</row><row r=\"2\" ht=\"22\" customHeight=\"1\">").Append(Cell("A2","按报名开始时间升序 · 已排除团日、班会和班级活动 · 共 "+data.Count+" 项",2)).Append("</row><row r=\"3\" ht=\"8\" customHeight=\"1\"/>");
            string[] headers={"活动名称","活动类型","发起组织","报名开始","报名截止","活动地点","活动时间","总名额","剩余名额","已报名","报名状态"};s.Append("<row r=\"4\" ht=\"28\" customHeight=\"1\">");for(int i=0;i<headers.Length;i++)s.Append(Cell(((char)('A'+i))+"4",headers[i],3));s.Append("</row>");DateTime now=DateTime.UtcNow.AddHours(8);
            for(int i=0;i<data.Count;i++){int r=5+i;var row=data[i];s.Append("<row r=\""+r+"\" ht=\"42\" customHeight=\"1\">");s.Append(Cell("A"+r,Str(row,"name"),5));s.Append(Cell("B"+r,Str(row,"type"),5));s.Append(Cell("C"+r,Str(row,"organizer"),5));s.Append(DateCell("D"+r,FirstDate(Str(row,"registration")),4));s.Append(DateCell("E"+r,LastDate(Str(row,"registration")),4));s.Append(Cell("F"+r,Str(row,"place"),5));s.Append(Cell("G"+r,Str(row,"activityTime"),5));s.Append(ValueCell("H"+r,Str(row,"capacity"),6));s.Append(ValueCell("I"+r,Str(row,"remaining"),6));s.Append(ValueCell("J"+r,Str(row,"registered"),6));s.Append(Cell("K"+r,ExcelStatus(row,now),5));s.Append("</row>");}
            if(data.Count==0)s.Append("<row r=\"5\"><c r=\"A5\" t=\"inlineStr\"><is><t>暂无符合条件的活动</t></is></c></row>");s.Append("</sheetData><mergeCells count=\"2\"><mergeCell ref=\"A1:K1\"/><mergeCell ref=\"A2:K2\"/></mergeCells><autoFilter ref=\""+range+"\"/><tableParts count=\"1\"><tablePart r:id=\"rId1\"/></tableParts></worksheet>");Entry(zip,"xl/worksheets/sheet1.xml",s.ToString());
