        bool VerifyExcel(string path,int expected){try{using(var zip=ZipFile.OpenRead(path)){ZipArchiveEntry sheet=zip.GetEntry("xl/worksheets/sheet1.xml"),table=zip.GetEntry("xl/tables/table1.xml"),styles=zip.GetEntry("xl/styles.xml");if(sheet==null||table==null||styles==null)return false;using(var reader=new StreamReader(sheet.Open(),Encoding.UTF8)){string xml=reader.ReadToEnd();return xml.Contains("ySplit=\"4\"")&&xml.Contains("tableParts")&&System.Text.RegularExpressions.Regex.Matches(xml,"<row r=\"").Count==expected+4;}}}catch{return false;}}
